"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[458],{3458:(a,e,o)=>{o.d(e,{f9:()=>t.f9,UI:()=>t.UI,xh:()=>t.xh,TG:()=>t.TG,uZ:()=>i,OE:()=>s});var l=o(9361),t=o(8957);let r={"word-counter":{name:"单词计数器",short:"统计任意文本的单词数、字符数、句子数和阅读时长。",intro:"粘贴或输入文本，即可随着书写实时查看单词数。本计数器还会同步统计字符数、句子数和段落数，并估算阅读所需时长——适用于作文、文章、演讲稿以及有字数限制的社交帖子。",howTo:["将文本粘贴或输入到文本框中。","查看计数结果——编辑时会即时更新。","使用「加载示例」查看使用效果，或使用「清除」重新开始。"],formula:"单词按由空格或标点分隔的字母或数字序列计数。阅读时长按成人平均阅读速度每分钟 200 个单词估算；朗读时长按每分钟 130 个单词估算。",exampleText:"示例段落（一段关于清晨的短文）包含 32 个单词。",faqs:[{q:"计数器会保存我的文本吗？",a:"不会。计数完全在您的浏览器中进行；不会上传或保存到服务器上。"},{q:"阅读时长是如何计算的？",a:"我们将单词数除以每分钟 200 个单词，这是成人默读常用的平均速度。您的实际速度可能更快或更慢。"},{q:"数字算作单词吗？",a:"算——一串数字如「2026」计为一个单词，这与大多数编辑器的计数方式一致。"}]},"character-counter":{name:"字符计数器",short:"统计含空格和不含空格的字符数，适用于帖子、广告和元文本。",intro:"字符限制无处不在：帖子、广告、短信、标题和元描述都有要求。此计数器会显示总字符数、不含空格的字符数，以及单词数和句子数，方便您将文本裁剪到符合任何限制。",howTo:["将文本粘贴到文本框中。","将「字符数」与您的限制对照；如果平台不计空格，再查看「不含空格的字符数」。","编辑文本，数字会实时更新。"],formula:"字符按 Unicode 码点计数，因此一个 emoji 计为一个字符。不含空格的数字会移除所有空白字符（空格、制表符和换行符）。",exampleText:"示例句子包含空格在内共有 47 个字符。",faqs:[{q:"为什么不同平台的字符计数方式不同？",a:"有些按字节计数，有些按 Unicode 码点计数，还有些（如 X/Twitter）会加权计算——URL 和许多 emoji 会计为不止一个字符。请将此计数视为纯文本长度。"},{q:"换行符算一个字符吗？",a:"算，每个换行符在总数中计为一个字符，在不含空格的统计中则会被排除。"}]},"sentence-counter":{name:"句子计数器",short:"统计句子数量，并检查平均句子长度。",intro:"冗长、绕口的句子很难阅读。此工具会统计文本中的句子数量，并报告每句的单词数，帮助您在编辑作文、文章或报告时找出需要拆分的段落。",howTo:["将文本粘贴到文本框中。","查看句子数和总单词数，以判断平均句子长度。","缩短或拆分长句后重新检查。"],formula:"句子以句号、问号或感叹号（包括「…」或「?!」等连续符号）结束，后面跟随更多文本或文本结尾。像「e.g.」这样的缩写可能会被不完美地计数——请将结果视为近似估算。",exampleText:"示例文本包含 3 句话。",faqs:[{q:"合适的平均句子长度是多少？",a:"通俗易懂的写作指南通常建议面向普通读者时平均每句 15–20 个单词，长短句交替以保持节奏。"},{q:"缩写会被正确处理吗？",a:"大多数情况下可以，但缩写内部的句号对简单的计数器来说可能看起来像句子结尾。遇到临界情况时请人工校对。"}]},"paragraph-counter":{name:"段落计数器",short:"统计结构化写作中的段落、单词和句子数量。",intro:"编辑和老师常为作文和文章设定段落目标。粘贴您的草稿即可统计段落数——段落指由空行或换行分隔的文本块——同时还会显示单词和句子总数。",howTo:["将结构化文本粘贴到文本框中。","查看段落数及辅助统计数据。","增加或合并段落后再次检查。"],formula:"段落是指由至少一个换行符与下一块分隔的非空文本块。空行会被忽略。",exampleText:"示例包含 3 个短段落。",faqs:[{q:"单个换行符会开启新段落吗？",a:"会。在此计数器中，任何换行符都会分隔段落，这与大多数粘贴草稿的结构一致。"},{q:"可以统计文档文件中的段落吗？",a:"将文档中的文本复制出来并粘贴到这里——本工具处理的是纯文本。"}]},"reading-time-calculator":{name:"阅读时长计算器",short:"估算文本的阅读或朗读所需时长。",intro:"博客平台会显示「5 分钟读完」是有原因的：读者会根据长度决定是否开始阅读。粘贴您的文章、脚本或演讲稿，即可按平均速度估算阅读时长，以及用于演示的朗读时长。",howTo:["将全文粘贴到文本框中。","查看估算的阅读时长和朗读时长。","如果是演讲，请先排练一次——您个人的语速是最好的校准标准。"],formula:"阅读时长 = 单词数 \xf7 每分钟 200 个单词。朗读时长 = 单词数 \xf7 每分钟 130 个单词。两者均为人群平均值，并非个人实测值。",exampleText:"一篇 1,000 个单词的文章大约需要 5 分钟读完，大声朗读大约需要 7–8 分钟。",faqs:[{q:"为什么是每分钟 200 个单词？",a:"关于成人阅读速度的研究表明，非虚构类默读的平均速度接近每分钟 200–250 个单词；200 是一个保守且广泛使用的数值。"},{q:"10 分钟的演讲需要多少单词？",a:"按每分钟 130 个单词计算，大约 1,300 个单词。请预留停顿时间以便强调和等待听众反应。"}]},"case-converter":{name:"大小写转换器",short:"将文本转换为大写、小写、标题大小写、camelCase 等格式。",intro:"不小心开着大写锁定打字了？需要标题使用 Title Case，或标识符使用 snake_case？粘贴文本，选择一种样式，即可复制转换后的结果——无需重新输入。",howTo:["将文本粘贴到文本框中。","从列表中选择一种大小写样式。","使用复制按钮复制结果。"],formula:"Title Case 将每个单词的首字母大写。camelCase 将单词无空格连接，除第一个单词外其余单词首字母大写；PascalCase 则将所有单词首字母都大写。snake_case 和 kebab-case 用 _ 或 - 连接小写单词。",exampleText:"“the quick brown fox”在 Title Case 中变为“The Quick Brown Fox”，在 camelCase 中变为“theQuickBrownFox”。",faqs:[{q:"我的文本会被上传吗？",a:"不会。转换仅在您的浏览器中运行。"},{q:"程序员使用哪种大小写格式？",a:"JavaScript 中的变量使用 camelCase，类名使用 PascalCase，Python 中使用 snake_case，URL 和 CSS 中使用 kebab-case。"}]},"json-formatter":{name:"JSON 格式化工具",short:"在浏览器本地以您选择的缩进方式美化打印 JSON。",intro:"来自 API 的压缩 JSON 很难阅读。将其粘贴到这里，即可使用整洁的缩进进行格式化——2 个空格、4 个空格、制表符或压缩格式——并通过指向问题位置的消息捕获语法错误。您的 JSON 永远不会离开您的设备，这在包含真实数据时尤为重要。",howTo:["将 JSON 粘贴到输入框中。","选择一种缩进样式。","选择「格式化」并复制结果。"],formula:"文本使用浏览器内置的 JSON 解析器（ECMA-404 / RFC 8259）进行解析，并按所选缩进重新序列化。源文件中的键顺序会被保留。",exampleText:"格式化示例可将单行对象转换为可读的、带缩进的文档。",faqs:[{q:"我的 JSON 会被发送到服务器吗？",a:"不会。格式化使用浏览器中的 JavaScript 完成；不会上传、记录或共享任何内容。避免将机密信息粘贴到任何您无法控制的在线工具中——本工具完全在页面内离线运行。"},{q:"为什么我的数字略有变化？",a:"JSON 数字按双精度浮点数解析。非常长的整数（超过 15–16 位）可能会丢失精度——如果精确数字很重要，请将 ID 保留为字符串。"},{q:"可以格式化 JSON 数组吗？",a:"可以。任何有效的 JSON 值——对象、数组、字符串、数字、布尔值或 null——都可以格式化。"}]},"json-validator":{name:"JSON 校验器",short:"检查 JSON 是否有效，并准确指出出错位置。",intro:"一个多余的尾随逗号就可能导致 API 调用失败。粘贴可疑的 JSON 进行校验：您会得到明确的有效/无效结论、解析器的错误消息，以及通过时顶层值的摘要。",howTo:["粘贴您要检查的 JSON。","选择「校验」。","如果校验失败，请阅读错误信息，修复其指出的位置，然后再次校验。"],formula:"校验是根据 JSON 语法（RFC 8259）进行的完整解析：字符串和键必须使用双引号，不允许尾随逗号，不允许注释，不允许单引号。",exampleText:"示例是描述一本书的有效 JSON。",faqs:[{q:"最常见的 JSON 错误有哪些？",a:"尾随逗号、使用单引号的字符串、未加引号的键、注释，以及粘贴到字符串中的控制字符。"},{q:"JSON 有效就意味着我的 API 一定会接受吗？",a:"不一定——校验只检查语法。API 仍可能因其自身的模式或业务规则而拒绝某些值。"}]},"base64-encoder":{name:"Base64 编码器",short:"将文本编码为 Base64（支持 UTF-8），且不会将数据发送到任何地方。",intro:"Base64 将二进制或非 ASCII 文本转换为纯 ASCII 文本，可安全地嵌入 JSON、URL、电子邮件和 data URI 中。此编码器会先将文本编码为 UTF-8，从而正确处理 Unicode。",howTo:["输入或粘贴您的文本。","选择「编码」。","复制 Base64 输出结果。"],formula:"文本被编码为 UTF-8 字节；每 3 个字节转换为 4 个 Base64 字符，字符来自字母表 A–Z、a–z、0–9、+ 和 /，并使用 = 填充至 4 的倍数。",exampleText:"“Hello, world!”编码为 SGVsbG8sIHdvcmxkIQ==。",faqs:[{q:"Base64 是加密吗？",a:"不是。Base64 是一种可逆编码，任何人都可以立即解码。切勿用它来保护密码或机密信息。"},{q:"为什么输出变长了？",a:"Base64 会使数据膨胀约 33%——3 个字节变为 4 个字符。"}]},"base64-decoder":{name:"Base64 解码器",short:"将 Base64 解码回可读的 UTF-8 文本，并捕获无效输入。",intro:"在日志、令牌载荷或电子邮件头中收到了 Base64 字符串？将其粘贴到这里即可解码回文本。格式错误的输入会被拒绝，并给出通俗易懂的错误提示，而不是静默地产生乱码。",howTo:["粘贴 Base64 字符串。","选择「解码」。","复制解码后的文本。"],formula:"字符串会根据 Base64 字母表进行校验，转换回字节，并按 UTF-8 解码。无效的 UTF-8 字节序列会被报告为错误。",exampleText:"SGVsbG8sIHdvcmxkIQ== 解码为“Hello, world!”。",faqs:[{q:"为什么解码失败了？",a:"常见原因包括：缺少 = 填充、包含 Base64 字母表之外的字符（URL 安全变体使用 - 和 _ 代替 + 和 /），或者解码后的字节是二进制数据而非文本。"},{q:"可以解码 JWT 吗？",a:"JWT 的头部和载荷使用的是 Base64URL，而不是普通 Base64。请先将 - 替换为 +、_ 替换为 /，然后再逐部分解码。"}]},"url-encoder":{name:"URL 编码器",short:"对用于 URL 和查询字符串的文本进行百分号编码（encodeURIComponent）。",intro:"空格、& 符号和非英文字符如果不进行百分号编码，就会破坏 URL。粘贴文本即可安全编码——为查询字符串值选择组件模式，或选择完整 URL 模式以保留 : / ? 等结构字符。",howTo:["粘贴文本或 URL。","查询值请保持「component」模式开启；完整 URL 请将其关闭。","选择「编码」并复制结果。"],formula:"UTF-8 编码中每个保留字节或非 ASCII 字节都写为 % 后跟两位十六进制数字。组件模式（encodeURIComponent）还会编码 / ? & = 等类似字符。",exampleText:"“fish & chips”在组件模式下编码为 fish%20%26%20chips。",faqs:[{q:"两种模式有什么区别？",a:"encodeURIComponent 用于 URL 中的单个值（它会编码所有结构字符）。encodeURI 用于完整的 URL，并会保留其结构。"},{q:"空格是 %20 还是 +？",a:"在基于百分号编码构建的 URL 路径或查询值中，%20 是正确的。+ 形式出现在表单提交中（application/x-www-form-urlencoded）。"}]},"url-decoder":{name:"URL 解码器",short:"将百分号编码的 URL 解码回可读文本。",intro:"百分号编码的 URL 难以阅读：到处都是 %20、%26、%C3%A9。将其粘贴到这里即可解码回普通文本，以便检查查询参数、文件名和重定向。",howTo:["粘贴已编码的文本。","单个值请保持「component」模式开启；完整 URL 请将其关闭。","选择「解码」。"],formula:"每个 %XX 十六进制对都会转换回其字节，字节序列按 UTF-8 解码。无效序列（例如 %ZZ 或孤立的 %）会被报告，而不是被猜测处理。",exampleText:"fish%20%26%20chips 解码为“fish & chips”。",faqs:[{q:"为什么会出现错误？",a:"输入可能包含不完整的转义序列（末尾的 %）或 0–9 A–F 范围之外的十六进制数字。"},{q:"它会将 + 解码为空格吗？",a:"decodeURIComponent 不会将 + 转换为空格。如果字符串来自表单提交，请先将 + 替换为空格。"}]},"password-generator":{name:"密码生成器",short:"在本地生成高强度随机密码——可自选长度和字符类型。",intro:"强密码的特点是长且随机，而不是一个单词后面加个数字。本工具使用浏览器内置的密码学安全随机源（crypto.getRandomValues）在你的设备上为你生成密码，长度和字符类型由你自选。密码不会发送到任何服务器，只存在于你的设备上，直到你复制它。",howTo:["选择密码长度——16 个字符以上是比较好的默认值。","勾选要包含的字符类型（大写字母、小写字母、数字、符号）。","点击「生成密码」，再用复制按钮复制结果。"],formula:"熵值衡量密码被猜中的难度：熵值（比特）= 长度 \xd7 log₂（字符集大小）。一个 16 个字符、使用全部四类字符（共 87 个字符）的密码约有 103 比特熵——即使攻击者以每秒 100 亿次的速度离线暴力破解，平均也需要一万亿年以上。密码使用浏览器密码学安全随机源生成，绝不使用 Math.random。",exampleText:"一个 16 个字符、使用全部四类字符的密码约有 103 比特熵，强度评级为「非常强」。",faqs:[{q:"生成的密码会被发送到服务器吗？",a:"不会。生成过程使用浏览器内的 crypto.getRandomValues 完成；密码永远不会离开你的设备。"},{q:"密码应该多长？",a:"至少 12 个字符，16 个字符以上更好——长度比增加符号更重要。对于重要的账号，请使用密码管理器，并为每个账号设置不同的密码。"},{q:"为什么工具保证每种已选字符类型至少出现一个？",a:"有些网站要求密码至少包含一个大写字母、数字或符号。生成时保证每类至少出现一个，可以让密码在这些网站上直接可用，同时几乎不削弱随机性。"},{q:"「排除易混淆字符」有什么作用？",a:"它会去掉朗读或手抄时容易混淆的字符——l、o、1、I、O 和 0——这样手动抄写密码时更不容易出错。"}]},"qr-code-generator":{name:"二维码生成器",short:"为文本、链接、Wi-Fi、名片等生成二维码——带商家常用模板，免费、私密，可下载 PNG 或 SVG。",intro:"二维码能把链接、文本、Wi-Fi 密码或联系方式变成手机一扫即得的图案。本工具在你的浏览器本地生成二维码，不上传任何内容：可选现成模板（网址、纯文本、Wi-Fi、名片、电话、短信、邮件、地图位置、日历日程、WhatsApp）填空生成，也可以像以前一样直接输入任意文本；可调节容错级别、尺寸和颜色，下载 PNG 或 SVG 用于打印、海报、名片、菜单或店面台卡。",howTo:["选择内容类型——Wi-Fi、名片等模板，或自由文本。","按模板填好字段（或直接输入链接、文本）。","选择容错级别与下载尺寸，可按需调整码色和背景色。","点击「下载 PNG」或「下载 SVG」保存二维码；用手机相机扫码测试。"],formula:"二维码将数据编码为黑白方块（模块）组成的网格：版本 1 为 21\xd721 个模块，每升一级每边增加 4 个模块，最高版本 40（177\xd7177）。容错级别决定二维码受损后仍可读取的比例：L 约 7%、M 约 15%、Q 约 25%、H 约 30%。级别越高，可容纳的内容越少；字节模式下，版本 40 的 L 级最多可容纳约 2,953 个字节。「QR Code」是 DENSO WAVE INCORPORATED 的注册商标。",exampleText:"示例链接 https://ducheng980-coder.github.io/ 在 M 级容错下生成版本 2 二维码（25\xd725 个模块）。",faqs:[{q:"生成的内容会被上传到服务器吗？",a:"不会。编码完全在你的浏览器本地完成；内容永远不会离开你的设备。"},{q:"应该选择哪个容错级别？",a:"一般用途选 M（默认）。如果二维码会被打印在容易磨损、遮挡的位置，或要在中间叠加小 logo，选择 Q 或 H；如果内容很长、接近容量上限，选择 L。"},{q:"二维码有有效期吗？",a:"没有。静态二维码把内容直接编进图案里，不依赖任何服务器，印出来后永久有效——前提是它指向的链接本身仍然可用。"},{q:"PNG 和 SVG 应该下载哪一个？",a:"PNG 是位图，适合直接在网页、聊天软件里使用；SVG 是矢量图，放大到任意尺寸都不会模糊，更适合印刷、海报和名片。"}]},"uuid-generator":{name:"UUID 生成器",short:"批量生成 v4 或按时间排序的 v7 UUID——免费、私密，还能解析任意 UUID 的版本与时间戳。",intro:"UUID（通用唯一识别码）是一个 128 位标识符，写作 32 位十六进制数字，按 8-4-4-4-12 分组——是为数据库记录、API 资源和文件生成永不冲突 ID 的标准做法。本工具使用浏览器 Web Crypto API 在本地生成 v4（随机）或 v7（按时间排序，RFC 9562）UUID，一次可生成 1 个或批量生成最多 100 个；还可以解析你粘贴的任意 UUID：显示其版本、变体，以及 v1、v6、v7 的创建时间。",howTo:["选择 v4（随机）或 v7（按时间排序）。","设置需要生成的数量（1–100），选择输出格式。","点击「生成 UUID」，再一键复制全部或下载为 .txt 文件。要解析已有的 UUID，请粘贴到下方并点击「解析」。"],formula:"v4 UUID 包含 122 位随机位：约有 5.3\xd710\xb3⁶ 种可能取值，两个独立生成的 v4 UUID 碰撞的概率在实际中可以忽略。v7 UUID 开头是 48 位 Unix 毫秒时间戳，因此新生成的 ID 天然排在旧 ID 之后——适合用作数据库主键——其后是 62 位随机位。两者都按标准设置版本位（4 或 7）和变体位（10xx，即 RFC 4122 变体）。",exampleText:"一次生成 5 个 v7 UUID，会得到 5 个按时间排序的 ID，它们在当前毫秒内共享相同的时间戳前缀。",faqs:[{q:"生成的 UUID 会被发送到服务器吗？",a:"不会。生成过程使用浏览器内的 crypto.getRandomValues 完成；UUID 永远不会离开你的设备，也不会被保存。"},{q:"v4 和 v7 应该选哪一个？",a:"v4（随机）是通用 ID 的安全默认选择。v7 更适合做数据库主键，因为它的时间戳前缀让新记录天然排在旧记录之后，索引更紧凑。一次性 ID 用哪个都可以。"},{q:"两个生成的 UUID 有可能相同吗？",a:"实际中不会。v4 UUID 有 122 位随机位，大约需要生成 2.7\xd710\xb9⁸（2.7 百万万亿）个，才有 50% 的概率出现一次重复。"},{q:"解析器对 v4 UUID 会显示什么？",a:"显示其版本（4）和变体（RFC 4122）。v4 UUID 不包含时间戳，因此不会显示创建时间——只有 v1、v6 和 v7 才编码了生成时间。"}]},"internet-speed-test":{name:"网速测试",short:"测一测你的网络：延迟（Ping）与抖动、下载速度与上传速度（Mbps），节点为 Cloudflare 全球网络。",intro:"你办的宽带到底有没有跑满？点击开始，本工具会在约二十秒内测三项：延迟（Ping）与抖动（延迟稳不稳定）、下载速度（Mbps）、上传速度（Mbps）。测速在你的浏览器与 Cloudflare 全球网络之间进行——用的就是知名开源测速工具常用的那组测量端点——国内国外用户用法一致，无需注册、无需安装。",howTo:["点击「开始测速」并等待——先测延迟，再测下载，最后测上传。","查看三个大字结果：延迟（含抖动）、下载 Mbps、上传 Mbps。","想复测（比如挪到路由器旁边、换个网络之后），点击「重新测速」。"],formula:"延迟：向 speed.cloudflare.com 发 10 次极小请求取往返时间（第一次要付建连成本，丢弃不用）；抖动为相邻两次往返时间变化的平均值。下载：在约 10 秒内从 Cloudflare 的 __down 端点分级拉取 100 KB 到 50 MB 的文件；上传：在约 10 秒内向 __up 端点分级发送浏览器生成的随机数据。速度（Mbps）= 总传输比特数 \xf7 总秒数 \xd7 1,000,000——用总量算而不是平均每档速度，长传输的权重才正确。",exampleText:"健康的家庭光纤一般能测到延迟约 10–40 ms、抖动低于 5 ms，且在没人抢网时下载/上传速度接近套餐标称值。",faqs:[{q:"为什么测出来比套餐标称低？",a:"本测试测的是你的设备到 Cloudflare 节点这一段路，Wi-Fi 信号、路由器负载、其他设备、VPN、节点距离都会影响。用网线连接、靠近路由器、暂停其他下载再测，结果最公平。"},{q:"测一次要用多少流量？",a:"取决于你的网速：下载与上传各在约 10 秒后停止，快网络一次可能传几百 MB，慢网络则少得多。手机流量有上限时不要反复测。"},{q:"上传阶段传的是我的文件吗？",a:"不是。只有浏览器现场生成的随机字节（crypto.getRandomValues），从不读取你的文件；Cloudflare 收到后即丢弃，它存在的唯一目的就是被计时。"},{q:"为什么每次测的结果不一样？",a:"网络是共享的，状况每分钟都在变。建议在一天里不同时段测两三次，看趋势而不是盯单次数字。"}]},"ip-lookup":{name:"IP 地址查询",short:"查看你的公网 IP、近似位置、运营商与 ASN——也可以查询任意 IPv4 / IPv6 地址。",intro:"每台上网设备都有一个公网 IP 地址，这个地址能大致看出连接来自哪里、由哪家运营商提供。本页打开即自动显示你自己的 IP 信息——IP 地址、国家/地区、城市、运营商（ISP）、ASN、时区——数据来自免费服务 ipwho.is，ipapi.co 为备用。也可以输入任意 IPv4 或 IPv6 地址查询同样的信息；页面下方还列出你的浏览器在本地报告的信息（浏览器标识、语言、屏幕尺寸、时区）供对照。",howTo:["打开页面——你自己的公网 IP 信息会自动加载。","要查别的地址，在输入框填入 IPv4 或 IPv6 地址，点击「查询」。","点击「查看我的 IP」可回到自己的地址。"],formula:"页面向第三方 IP 地理数据库接口查询该地址（先 ipwho.is，失败则用 ipapi.co 备用）；该服务把地址与 IP 分配数据库比对，返回登记的国家、地区、城市、运营商、ASN 与时区。定位是近似的——数据库通常定位到运营商的路由节点，不是街道地址——并且待查 IP 会被发送给该接口，它才能返回结果。",exampleText:"查询 8.8.8.8（谷歌公共 DNS 地址）会得到：美国、组织为 Google LLC、ASN 为 AS15169。",faqs:[{q:"定位有多准？",a:"国家级通常准确；城市级是近似值，可能偏差几十公里，因为数据库定位的是运营商的基础设施而不是你家。切勿把 IP 定位当成街道地址。"},{q:"为什么显示的城市不是我住的城市？",a:"你的运营商可能把流量从区域枢纽送出，移动网络更是常常从外地出口。用了 VPN 或代理时，查到的就是 VPN 服务器的地址，与你本人无关。"},{q:"我的 IP 会被本站保存吗？",a:"不会——本站没有自己的服务器。你的浏览器会通过 HTTPS 把待查地址直接发给地理数据库接口（ipwho.is，或备用 ipapi.co），该请求受对方自己隐私政策的约束。"},{q:"什么是 ASN？",a:"ASN（自治系统号）标识在全球路由系统中宣告某个 IP 段的网络运营商——例如 AS15169 属于谷歌。它是判断一个地址归属哪家组织最快的办法。"}]},"x-post-analyzer":{name:"X 热帖数据分析",short:"分析任意公开的 X（推特）帖子：观看量、点赞、转发、收藏、互动率，以及预估的创作者分成。",intro:"想知道一条爆款帖到底值多少钱？把任意公开 X（推特）帖子的链接粘贴进来，本工具通过免费的 FxTwitter 接口拉取它实时的公开计数——观看、点赞、转发、回复、引用、收藏——再算出大家真正关心的数字：总互动数、互动率、收藏率、平均每小时观看量、参考热度分档，以及这条帖子可能拿到的创作者分成粗估。以后再看到「一帖 50 万观看」这类说法，先来这里核一遍数字再决定信不信。",howTo:["粘贴完整的 X 帖子链接（x.com 或 twitter.com 都可以，带参数的分享链接也没问题）。","点击「分析帖子」，查看计数与比率。","点击「试试示例帖子」，直接看一条真实爆款帖的完整分析。"],formula:"总互动数 = 点赞 + 转发 + 回复 + 引用 + 收藏。互动率 = 总互动数 \xf7 观看量；收藏率 = 收藏 \xf7 观看量；点赞率 = 点赞 \xf7 观看量。平均每小时观看 = 观看量 \xf7 发布至今的小时数。热度分档为按观看量的参考标尺：1 万以下普通、1 万–10 万热门、10 万–50 万爆款、50 万以上现象级。分成预估 = 观看量 \xd7 每 100 万次观看 $8–12，再按 1 美元≈7.1 元折算——它假设全部观看都是合格观看，而真实分成从来不是这样算的（见常见问题）。",exampleText:"示例帖子——@404jsh 的一篇长文——观看量超过 20 万、收藏超过 2,100，互动率约 1.5%，按上述口径预估分成约 $1.6–$2.5（约 \xa512–\xa517）。",faqs:[{q:"数据从哪来？",a:"你的浏览器直接向免费公开接口 FxTwitter（api.fxtwitter.com）查询这条帖子。它同步的是 X 本身展示的公开计数，所以数字是你点击分析这一刻的真实公开数据——帖子继续传播，数字还会变。"},{q:"分成预估准吗？",a:"请把它当成乐观上限，不是预测。X 只按 Premium（付费）用户的互动给创作者分成，而且账号要先满足资格——开通 Premium、粉丝至少 500、近 3 个月曝光 500 万次，还有最低打款门槛。绝大多数观看不是 Premium 互动，所以真实分成通常远低于预估；没资格的账号则一分钱都没有。"},{q:"哪些链接能查？",a:"x.com 或 twitter.com 的任意公开帖子链接，包括带跟踪参数的分享链接和带 /photo/1 后缀的链接。已删除的帖子、设为保护（私密）账号的帖子取不到数据。"},{q:"我粘贴的链接会被保存吗？",a:"本站不会保存。你的浏览器通过 HTTPS 把帖子标识直接发给 api.fxtwitter.com，结果也直接回传到你的浏览器，页面不留副本。和本站其他工具一样，我们只记录一条匿名的「工具被使用过」计数用于自家统计。"}]},"age-calculator":{name:"年龄计算器",short:"根据出生日期计算精确年龄，精确到年、月、日。",intro:"输入出生日期，即可得到精确年龄——年、月和日——以及已生活的总周数和总天数，还有距离下一次生日的倒计时。还可以填写「计算年龄的日期」，算出某人在任意指定日期当时或将来的年龄，适用于填表、入学报名或资格审核等场景。",howTo:["输入出生日期。","可选填「计算年龄的日期」（默认为今天）。","点击「计算」查看完整明细。"],formula:"年龄按真实日历计算：先算满的年数，再算满的月数，最后算剩余天数——与官方表格采用的口径一致。对于 2 月 29 日出生的人，在非闰年其生日按所在司法管辖区的规定视为 2 月 28 日或 3 月 1 日；本工具按所输入日期的日历算术计算。",exampleText:"1990 年 6 月 15 日出生的人，在 2026 年 6 月 15 日满 36 岁。",faqs:[{q:"为什么我算出的年龄和另一个计算器差一天？",a:"有些工具按每月固定 30 天计算，或把起止两天都计入。本工具采用精确的日历算术，与官方文件口径一致。"},{q:"可以计算历史人物的年龄吗？",a:"可以——把「计算年龄的日期」设为其去世日期（或任意日期），即可得到那一时刻的年龄。"},{q:"我的出生日期会被保存吗？",a:"不会。计算在您的浏览器中完成，不会向任何地方发送数据。"}],fields:{dob:{label:"出生日期"},asof:{label:"计算年龄的日期（可选）"}}},"date-calculator":{name:"日期计算器",short:"在任意日期上加减天、周、月和年。",intro:"需要知道从现在起 90 天后是哪一天，或某个截止日期前 6 个月是哪一天？选择起始日期，选择加或减，再输入天、周、月或年的数量。结果会显示新日期、星期几，以及实际移动了多少天。",howTo:["选择起始日期。","选择加或减，并选择单位（天、周、月、年）。","输入数量，然后点击「计算」。"],formula:"天和周按精确天数计算。月和年采用日历算术，遇到较短的月份会钳制到月末（例如，1 月 31 日 + 1 个月 = 2 月的最后一天）。",exampleText:"2026 年 3 月 1 日 + 90 天 = 2026 年 5 月 30 日。",faqs:[{q:"为什么 1 月 31 日 + 1 个月不是 3 月 3 日？",a:"按日历加月时，会尽量保持相同的日，无法保持时则钳制到最后一个有效日——2 月没有 31 日。"},{q:"它计算工作日吗？",a:"不计算——本计算器移动的是日历天。日期差计算器会报告两个日期之间的工作日数量。"}],fields:{start:{label:"起始日期"},operation:{label:"操作",options:{add:"加",subtract:"减"}},amount:{label:"数量"},unit:{label:"单位",options:{days:"天",weeks:"周",months:"月",years:"年"}}}},"date-difference-calculator":{name:"日期差计算器",short:"计算两个日期之间精确的间隔，精确到年、月、日。",intro:"一个起始日期和结束日期之间相隔多久——无论是项目周期、租约期限还是倒计时？输入两个日期，即可得到以年、月、日表示的间隔，以及总天数、总周数和两者之间的工作日数量。",howTo:["输入起始日期。","输入结束日期（顺序不限）。","可选择将结束日期本身计入天数，然后计算。"],formula:"明细先减日历年，再减月，最后减日，月份长度按真实日历借位。总天数是两个日期在午夜时刻的精确差值。",exampleText:"从 2026 年 1 月 1 日到 2026 年 12 月 31 日是 364 天（如果计入结束日期，则为 365 天）。",faqs:[{q:"为什么总数比我预期的少一天？",a:"差值计算的是日期之间的步数，而不是日期本身。开启「将结束日期计入天数」，即可把起止两端都计入，这也是许多倒计时的做法。"},{q:"工作日是如何计算的？",a:"工作日（周一至周五）严格计算在起始日期和结束日期之间，适用于请假和截止日期规划。"}],fields:{start:{label:"起始日期"},end:{label:"结束日期"},includeEnd:{label:"是否将结束日期计入天数？",options:{no:"否",yes:"是"}}}},"days-between-dates":{name:"两日期间天数计算器",short:"简单直接地计算两个日期之间的天数。",intro:"有时您只需要一个数字：两个日期之间有多少天。输入起始日期和结束日期即可得到天数，并附带周数、约略月数和工作日数量作为参考明细。",howTo:["输入起始日期。","输入结束日期。","点击「计算」——标题数字就是天数。"],formula:"天数 = 结束日期 − 起始日期，按您本地时区的午夜时刻计算，因此夏令时切换不会影响计数。",exampleText:"2026 年 3 月 1 日到 2026 年 5 月 14 日之间有 74 天。",faqs:[{q:"日期的顺序重要吗？",a:"不重要。如果结束日期更早，工具会交换两者并报告间隔；总天数仍保留结束日期减去起始日期的符号。"},{q:"它和日期差计算器有什么区别？",a:"本页以简单的天数为主；日期差计算器以年/月/日明细为主。底层计算完全相同。"}],fields:{start:{label:"起始日期"},end:{label:"结束日期"},includeEnd:{label:"是否将结束日期计入天数？",options:{no:"否",yes:"是"}}}},"time-calculator":{name:"时间计算器",short:"在一天中的某个时刻（HH:MM:SS）上加减时长。",intro:"21:30 之后 2 小时 45 分钟是几点？在起始时间上加或减一段时长，即可得到结果时刻，包括向前或向后跨越了多少天。",howTo:["按 HH:MM 或 HH:MM:SS 格式输入起始时间。","选择加或减。","按相同格式输入时长，然后计算。"],formula:"先把时间换算成秒，加或减之后，再换算回 24 小时制时刻；溢出的整天数会单独报告。",exampleText:"21:30 + 2:45 = 次日 00:15。",faqs:[{q:"时长可以超过 24 小时吗？",a:"可以。最多接受 999 小时的时长，天数偏移会显示在结果旁边。"},{q:"它支持上午/下午（AM/PM）吗？",a:"请按 24 小时制输入时间（例如下午 2:30 输入 14:30），以避免歧义。"}],fields:{base:{label:"起始时间 (HH:MM:SS)",placeholder:"21:30:00"},operation:{label:"操作",options:{add:"加",subtract:"减"}},duration:{label:"时长 (HH:MM:SS)",placeholder:"02:45:00"}}},"percentage-calculator":{name:"百分比计算器",short:"即时计算一个数值的百分之几是多少。",intro:"最常见的百分比问题：Y 的 X% 是多少？输入百分比和数值，即可得到结果、剩余值和计算过程。适用于小费、佣金、考试分数和折扣。",howTo:["输入百分比。","输入它所作用的数值。","点击「计算」。"],formula:"结果 = (百分比 \xf7 100) \xd7 数值。显示的剩余值 = 数值 − 结果。",exampleText:"240 的 15% 是 36。",faqs:[{q:"如何求一个数是另一个数的百分之几？",a:"用部分除以整体，再乘以 100。例如，36 \xf7 240 \xd7 100 = 15%。"},{q:"百分比可以超过 100 吗？",a:"可以。240 的 150% 是 360——结果只是比起始数值更大。"}],fields:{percent:{label:"百分比 (%)"},value:{label:"数值"}}},"percentage-increase-calculator":{name:"百分比增长计算器",short:"以百分比衡量从一个数值到另一个数值的增长。",intro:"价格、工资、流量、成绩——当某样东西增长时，本工具将增长表示为占起始值的百分比，并同时给出绝对变化量。",howTo:["输入起始（原始）值。","输入新值。","点击「计算」。"],formula:"百分比增长 = ((新值 − 原始值) \xf7 |原始值|) \xd7 100。如果新值更小，结果为负数——工具会提示这实际上是下降。",exampleText:"从 80 到 100 是增长 25%。",faqs:[{q:"为什么要除以起始值？",a:"百分比变化始终相对于起点。从 80 涨到 100（+20）是 +25%；反过来从 100 跌到 80 则是 −20%。"},{q:"如果起始值为零会怎样？",a:"从零出发的百分比变化无定义（除以零），因此工具会要求更换起始值。"}],fields:{from:{label:"起始值"},to:{label:"新值"}}},"percentage-decrease-calculator":{name:"百分比下降计算器",short:"以百分比衡量从一个数值到另一个数值的下降。",intro:"当价格下调或某项指标下跌时，本工具将下降表示为占原始值的百分比，并给出绝对变化量作为参考。",howTo:["输入原始值。","输入降低后的值。","点击「计算」。"],formula:"百分比变化 = ((新值 − 原始值) \xf7 |原始值|) \xd7 100。下降显示为负百分比；如果数值实际上上升了，工具会予以说明。",exampleText:"从 120 跌到 90 是 −25% 的变化（下降 25%）。",faqs:[{q:"先下降 50% 再增长 50%，能回到起点吗？",a:"不能。100 → 50 是 −50%，但 50 → 100 是 +100%。由于基数变了，百分比变化并不对称。"},{q:"它和折扣有什么区别？",a:"折扣是从折扣百分比出发；本工具是从两个价格出发。折扣计算器的计算方向正好相反。"}],fields:{from:{label:"原始值"},to:{label:"降低后的值"}}},"fraction-calculator":{name:"分数计算器",short:"加、减、乘、除分数，并给出约分后的结果。",intro:"输入两个分数和一种运算。结果会约分到最简形式，并同时显示为小数和带分数——这正是学校作业和食谱真正需要的三种形式。",howTo:["输入第一个分数的分子和分母。","选择一种运算。","输入第二个分数，然后计算。"],formula:"加法和减法使用公分母（a/b \xb1 c/d = (ad \xb1 bc)/bd）。乘法是 (a\xd7c)/(b\xd7d)；除法是 (a\xd7d)/(b\xd7c)。结果会用最大公约数约分。",exampleText:"1/2 + 1/3 = 5/6 ≈ 0.833333。",faqs:[{q:"为什么分母必须是整数且不能为零？",a:"分数 a/b 的定义要求 a 和 b 为整数且 b ≠ 0。小数比例请使用百分比计算器。"},{q:"如何输入像 1\xbd 这样的带分数？",a:"先把它化成假分数：1\xbd = 3/2。或者分别计算整数部分和分数部分，再相加。"}],fields:{n1:{label:"分数 1 — 分子"},d1:{label:"分数 1 — 分母"},operation:{label:"运算",options:{add:"加 +",subtract:"减 −",multiply:"乘 \xd7",divide:"除 \xf7"}},n2:{label:"分数 2 — 分子"},d2:{label:"分数 2 — 分母"}}},"average-calculator":{name:"平均数计算器",short:"计算任意一组数字的平均值、中位数、众数、极差和几何平均数。",intro:"粘贴一组数字——用逗号、空格或换行分隔——一次得到平均值（算术平均）、中位数、众数、极差、总和和个数。适用于成绩、价格、测量数据和快速数据核查。",howTo:["输入您的数字，用逗号或空格分隔。","点击「计算」。","比较平均值和中位数——差距大说明异常值在拉动平均数。"],formula:"平均值 = 总和 \xf7 个数。中位数是排序后位于中间的值（或中间两个值的平均值）。众数是出现最频繁的值。几何平均数是乘积的 n 次根，这里定义于正数。",exampleText:"对于 4, 8, 15, 16, 23, 42：平均值是 18，中位数是 15.5。",faqs:[{q:"什么时候中位数比平均值更好？",a:"当少数特别大或特别小的值（异常值）会扭曲平均值时——收入和房价就是典型例子。"},{q:"如果每个数字只出现一次会怎样？",a:"那么就没有众数，工具会如实说明，而不是编造一个。"}],fields:{numbers:{label:"数字（用逗号或空格分隔）",placeholder:"4, 8, 15, 16, 23, 42"}}},"ratio-calculator":{name:"比值计算器",short:"化简比值，查看各部分占比，并按比分配总量。",intro:"输入两个数字来化简它们的比（适用于食谱、屏幕尺寸、地图和混合物），查看每一侧的百分比占比，还可以选择按该比分配一个总量。",howTo:["输入比值的两侧（a 和 b）。","可选输入要分配的总量。","点击「计算」。"],formula:"整数比通过两边同时除以它们的最大公约数来化简。占比分别为 a/(a+b) 和 b/(a+b)；总量按相同比例分配。",exampleText:"比 12:8 化简为 3:2，占比分别为 60% 和 40%。",faqs:[{q:"如何把比值放大？",a:"两边同时乘以同一个数——3:2 放大 10 倍是 30:20。如需分配金额，请改用总量字段。"},{q:"1920\xd71080 的宽高比是多少？",a:"1920:1080 化简为 16:9——输入 a=1920、b=1080 即可核查任意分辨率。"}],fields:{a:{label:"边 a"},b:{label:"边 b"},total:{label:"要分配的总量（可选）"}}},"tile-calculator":{name:"瓷砖用量计算器",short:"铺地砖需要买多少块？输入房间尺寸、瓷砖规格和铺法（含损耗），算出块数、箱数和备砖。",intro:"买地砖很容易算错：买少了，补货可能遇到不同批次的色差；买多了，退货要花钱。输入房间尺寸（或直接输入铺贴面积），选择瓷砖规格和铺法，本工具会算出净需块数、该铺法的损耗、应买多少箱，以及应留多少块备砖。",howTo:["输入房间长和宽（米），或直接输入铺贴面积（平方米）。","选择瓷砖规格（选「自定义规格」时再输入瓷砖长和宽，单位毫米），并选择铺法。","核对损耗率（已按铺法填入默认值；瓦工师傅给过其他数字就按他的改），填写每箱片数和备砖块数，点击「计算」。"],formula:"每平方米块数 = 1 \xf7（瓷砖长 \xd7 瓷砖宽，单位米）。净需块数 = 向上取整（面积 \xf7 单块面积）。含损耗块数 = 向上取整（面积 \xf7 单块面积 \xd7（1 + 损耗率））。箱数 = 向上取整（（含损耗块数 + 备砖）\xf7 每箱片数）。损耗率默认值为各铺法常用区间的中值：直铺 5.5%、工字铺 6.5%、斜铺 45\xb0 与人字铺 11%、鱼骨铺 13.5%。",exampleText:"4 米 \xd7 3 米的房间，用 800 \xd7 800 毫米瓷砖直铺：含损耗 20 块，买 9 箱（每箱 3 块，共 27 块），其中含 5 块备砖。",faqs:[{q:"为什么铺法会影响损耗率？",a:"直铺和工字铺主要在边角切割，5–7% 通常够用。斜铺、人字铺和鱼骨铺要斜切瓷砖，浪费更多，一般为 10–15%。工具会按所选铺法填入常用区间的中值；瓦工师傅给过其他数字时以他的为准。"},{q:"为什么要留备砖？",a:"不同生产批次的瓷砖颜色可能略有差异，几年后单块瓷砖破了也很难配到同一批。留 5–10 块同一批次的整砖备用，是行业常见做法。"},{q:"房间不是长方形怎么办？",a:"先量出净铺贴面积（总面积减去浴缸、固定柜等固定设施占用的面积），填到「铺贴面积」字段中，它会覆盖长 \xd7 宽的计算。L 形等切割多的房间，可再适当提高损耗率。"}],fields:{length:{label:"房间长（米）"},width:{label:"房间宽（米）"},area:{label:"铺贴面积（平方米）——可选，覆盖长 \xd7 宽"},tileSize:{label:"瓷砖规格",options:{"300x300":"300 \xd7 300 毫米","300x600":"300 \xd7 600 毫米","600x600":"600 \xd7 600 毫米","800x800":"800 \xd7 800 毫米","600x1200":"600 \xd7 1,200 毫米","750x1500":"750 \xd7 1,500 毫米",custom:"自定义规格"}},tileL:{label:"自定义瓷砖长（毫米）"},tileW:{label:"自定义瓷砖宽（毫米）"},layout:{label:"铺法",options:{straight:"直铺",brick:"工字铺",diagonal:"斜铺 45\xb0",herringbone:"人字铺",fishbone:"鱼骨铺"}},loss:{label:"损耗率（%）——可选，覆盖铺法默认值"},perBox:{label:"每箱片数"},spare:{label:"备砖块数"}}},"chargeable-weight-calculator":{name:"体积重/计费重计算器",short:"包裹体积重与计费重：输入箱子尺寸、实重与件数，选抛比口径（6000/5000/8000/12000/3000）与进位档，算出单件与整票计费重。",intro:"轻而大的包裹按体积收费，不按秤上的重量收费：承运方取实重与体积重里较大的那个计费，抛比选错了运费能差一倍。输入单只箱子的长、宽、高、单件实重与件数，选择你这条线路的抛比——国内快递与空运 6000、国际快递 5000、部分电商渠道 8000、顺丰同城/省内 12000、冷链重货 3000——再选进位档，本工具会算出体积、体积重、按哪方计费，以及单件与整票计费重，旁边还附三档体积重对照。",howTo:["量出单只箱子的外长、外宽、外高（厘米），称出单件实重（千克）。","选择你这条线路的抛比（各渠道常用值已填好；货代给过其他数字就选「自定义抛比」手填），并选择进位档。","填写件数，点击「计算」——单件计费重先向上取整，再乘以件数。"],formula:"体积 = 长 \xd7 宽 \xd7 高。体积重 = 体积 \xf7 抛比。单件计费重 = max（实重，体积重）再按进位档向上取整。整票计费重 = 单件计费重 \xd7 件数。CBM = 体积 \xf7 1,000,000。抛比为参考值：国内快递/空运 6000（IATA）、国际快递 5000（DHL/FedEx/UPS）、部分电商渠道 8000、顺丰同城/省内 12000、冷链重货 3000。",exampleText:"60 \xd7 40 \xd7 30 厘米的箱子，实重 5 千克，1 件，走国内快递 \xf76000：体积重 12 千克，计费重按 12 千克算，不是 5 千克。同一个箱子按 \xf712000 只有 6 千克。",faqs:[{q:"为什么计费重比秤上的重量高？",a:"承运方既收重量、也收占用的空间。体积重是把箱子体积换算成千克（长 \xd7 宽 \xd7 高 \xf7 抛比），计费取实重与体积重里较大的那个。轻而大的箱子，计费重很容易是实重的两三倍。"},{q:"抛比该选哪一个？",a:"按承运方或货代给这条线路报的口径选：国内快递与空运常用 6000、国际快递（DHL、FedEx、UPS）5000、部分电商渠道 8000、顺丰同城/省内 12000、冷链重货 3000。顺丰标快在实重 30 千克处换挡——30 千克以下按 12000、30 千克及以上按 6000。拿不准就选「自定义抛比」，填报价单上的数字。"},{q:"为什么要按单件进位，而不是整票加总后再进位？",a:"承运方是先把每件向上取整、再把各件加起来；整票加总后再进位会把运费算少。本工具按同一顺序算：先取大、再进位、最后乘件数。"},{q:"这个工具能直接算出运费吗？",a:"不能——它算的是计费重，也就是费率要乘的那个重量。整票计费重 \xd7 线路单价（再加燃油附加费、最低收费等）才是运费。多种尺寸混装时，请按每种尺寸分别计算再相加。"}],fields:{length:{label:"长（厘米）"},width:{label:"宽（厘米）"},height:{label:"高（厘米）"},weight:{label:"单件实重（千克）"},pieces:{label:"件数"},divisor:{label:"抛比口径",options:{6e3:"国内快递 / 空运（\xf76000）",5e3:"国际快递（\xf75000）",8e3:"部分电商渠道（\xf78000）",12e3:"顺丰同城 / 省内（\xf712000）",3e3:"冷链重货（\xf73000）",custom:"自定义抛比"}},customDivisor:{label:"自定义抛比除数——仅自定义时填写"},rounding:{label:"进位档",options:{"0.5":"按 0.5 千克向上取整",1:"按 1 千克向上取整","0.1":"按 0.1 千克向上取整",none:"不进位"}}}},"cabinet-board-calculator":{name:"定制柜板材用量计算器",short:"定制柜子要买多少张板？两种算法：按投影面积 \xd7 展开系数快速估算，或输入柜体宽高深按侧板、顶底板、层板、抽屉、门板、背板逐件拆算，算出 18mm 主板与 9mm 背板各需多少张标准板（含损耗）。",intro:"定制柜买板很容易算错：报价单上的投影面积比实际展开的板材面积小得多，损耗率取错了还会导致补板遇到不同批次。本工具有两种算法：系数估算模式输入每种柜体的投影面积（或直接输入主板展开面积），按常用展开系数换算；按尺寸拆件模式输入单个柜体的外宽、外高、外深和中立板、层板、抽屉数量，把侧板、顶底板、层板、抽屉、门板、背板逐件算清。两种模式都会加上该板材的行业损耗，算出要买多少张 1220\xd72440mm 标准板——18mm 主板与 9mm 背板分开统计。",howTo:["先选计算模式：「系数估算」适合报价阶段快速算总量；「按尺寸拆件」适合把单个柜体逐件算清。","系数估算模式：输入每种柜体的投影面积（宽 \xd7 高，单位平方米），或直接输入主板展开面积（会覆盖柜体清单），需要时填写背板展开面积。按尺寸拆件模式：输入柜体宽、高、深（毫米）和中立板、层板、抽屉数量，选择门板算法；背板按宽 \xd7 高自动计算，不用手填。","选择板材种类（损耗率已按该板材的常用区间填入默认值；工厂给过其他数字就按他的改），如需估算费用可填写单张板价，点击「计算」。"],formula:"系数估算模式：展开面积 = 投影面积 \xd7 展开系数（衣柜 2.2、书柜 3.0、鞋柜 2.5、餐边柜 2.2，其他柜体默认 2.2）。按尺寸拆件模式（宽 W、高 H、深 D）：侧板 =（2 + 中立板数）\xd7 D \xd7 H；顶底板 = 2 \xd7 W \xd7 D；层板 = 层板数 \xd7 W \xd7 D；每个抽屉 = 抽面板 W \xd7 抽面高 + 两侧帮 2 \xd7 D \xd7 0.15 米 + 后板 W \xd7 0.15 米 + 底板 W \xd7 D（抽屉底板按 18mm 计、偏保守）；门板 = W \xd7 H（或手填面积、或不计）；背板 = W \xd7 H、按 9mm 单独统计。两种模式同口径：含损耗面积 = 面积 \xd7（1 + 损耗率）；张数 = 向上取整（含损耗面积 \xf7 2.9768），2.9768 平方米为一张 1220\xd72440mm 标准板的面积。损耗率默认值为该板材常用区间的中值：颗粒板 10%、多层板 12.5%、密度板 9%、进口板 12.5%。",exampleText:"按尺寸拆件模式：衣柜宽 2000、高 2400、深 600 毫米，中立板 1 块、层板 3 块、抽屉 2 个（抽面高 240），颗粒板——主板逐件合计 19.44 平方米（侧板 4.32 + 顶底板 2.4 + 层板 3.6 + 抽屉 4.32 + 门板 4.8），按 10% 损耗买 8 张；背板 4.8 平方米，买 2 张。",faqs:[{q:"投影面积和展开面积有什么区别？",a:"投影面积只是柜体正面（宽 \xd7 高）；展开面积是把侧板、顶板、底板、层板、背板全部拆开相加，所以大得多：衣柜约是投影面积的 2.2 倍，层板多的书柜约 3 倍。按投影面积报价时，单价里已经摊了展开系数；但买板必须按展开面积算。"},{q:"为什么主板和背板要分开算？",a:"柜体一般用 18mm 板，背板用更薄的 9mm 板，是两种不同价格的产品，工厂拆单时也是分开统计的。混在一起算会多买贵的 18mm 板。"},{q:"为什么不同板材的损耗率不一样？",a:"损耗来自开料裁边与边角余料，纹理方向也有影响：多层板要顺纹开料，损耗 10–15%；颗粒板一般 8–12%；密度板 8–10%。工具会按所选板材填入常用区间的中值；工厂拆单给过具体数字时以他的为准。"},{q:"拆件模式和系数模式有什么区别？",a:"系数模式是投影面积乘一个行业展开系数，快，报价阶段够用；但系数是平均数——中立板、抽屉多的柜子实际用板比系数多，结构简单的又比系数少。拆件模式按单个柜体的外尺寸逐件算：侧板、顶底板、层板、每个抽屉盒、门板、背板都单列，结果跟着柜子的实际结构走。拆件模式按外尺寸毛算、未扣板厚与封边，属备料估算，正式下单仍以工厂拆单清单为准。"}],fields:{mode:{label:"计算模式",options:{factor:"系数估算",detail:"按尺寸拆件"}},wardrobe:{label:"衣柜投影面积（平方米）"},bookshelf:{label:"书柜投影面积（平方米）"},shoe:{label:"鞋柜投影面积（平方米）"},sideboard:{label:"餐边柜投影面积（平方米）"},otherProj:{label:"其他柜体投影面积（平方米）"},otherCoeff:{label:"其他柜体展开系数"},mainArea:{label:"主板（18mm）展开面积（平方米）——可选，覆盖柜体清单"},backArea:{label:"背板（9mm）展开面积（平方米）"},cabW:{label:"柜宽（毫米）——拆件模式"},cabH:{label:"柜高（毫米）——拆件模式"},cabD:{label:"柜深（毫米）——拆件模式"},midPanels:{label:"中立板数量——拆件模式"},shelves:{label:"层板数量——拆件模式"},drawers:{label:"抽屉数量——拆件模式"},drawerFrontH:{label:"抽屉面高（毫米）——拆件模式"},doorMode:{label:"门板计算——拆件模式",options:{auto:"自动——按柜宽 \xd7 柜高",none:"不计门板",manual:"手填面积"}},doorArea:{label:"门板面积（平方米）——拆件模式\xb7手填时用"},boardType:{label:"板材种类",options:{particleboard:"颗粒板",multilayer:"多层板",mdf:"密度板",imported:"进口板"}},loss:{label:"损耗率（%）——可选，覆盖板材默认值"},price:{label:"单张板价（元）——可选"}}},"bmi-calculator":{name:"身体质量指数（BMI）计算器",short:"根据身高和体重计算身体质量指数，支持公制和英制。",intro:"身体质量指数（BMI）是一个将体重与身高进行比较的筛查指标。输入你的数据——可选择公制或英制——即可查看你的 BMI、对应的标准成人分类，以及适合你身高的健康体重范围。",howTo:["选择公制（kg、cm）或英制（lb、in）。","输入你的体重和身高。","点击「计算」。"],formula:"BMI = weight (kg) \xf7 height (m)\xb2。成人分类（WHO）：低于 18.5 为体重过轻，18.5–24.9 为健康，25–29.9 为超重，30+ 为肥胖。BMI 无法区分肌肉和脂肪，且不适用于儿童、运动员或孕期人群。",exampleText:"体重 70 kg、身高 175 cm 时，BMI 为 22.9——处于健康范围内。",faqs:[{q:"BMI 是诊断结果吗？",a:"不是。它只是一个粗略的筛查指标。身体成分、年龄、性别和种族等因素都会产生影响——请与专业医护人员讨论你的结果。"},{q:"BMI 适用于儿童吗？",a:"儿童应使用按年龄和性别划分的百分位数，而不是这里所示的成人临界值。"}],fields:{system:{label:"单位制",options:{metric:"公制（千克、厘米）",imperial:"英制（磅、英寸）"}},weight:{label:"体重"},height:{label:"身高"}}},"bmr-calculator":{name:"基础代谢率（BMR）计算器",short:"使用 Mifflin–St Jeor 公式计算基础代谢率。",intro:"基础代谢率是你的身体在完全静息状态下所消耗的能量。本计算器根据你的年龄、性别、体重和身高，采用 Mifflin–St Jeor 公式进行计算——这是目前最广泛推荐的估算方法。",howTo:["选择公制或英制。","输入性别、年龄、体重和身高。","点击「计算」。"],formula:"男性：BMR = 10\xd7kg + 6.25\xd7cm − 5\xd7age + 5。女性：BMR = 10\xd7kg + 6.25\xd7cm − 5\xd7age − 161。结果以千卡/天为单位。",exampleText:"一位 30 岁男性，体重 70 kg、身高 175 cm，其 BMR 约为 1,649 kcal/day。",faqs:[{q:"BMR 与每日总能量消耗（TDEE）有什么区别？",a:"BMR 仅指静息状态下消耗的能量。每日总能量消耗（TDEE）是将 BMR 乘以活动系数得到的——卡路里计算器会为你完成这一步计算。"},{q:"这个公式有多准确？",a:"它估算的是人群平均值；个体数值可能相差约 \xb110%。间接测热法是临床测量方法。"}],fields:{system:{label:"单位制",options:{metric:"公制（千克、厘米）",imperial:"英制（磅、英寸）"}},sex:{label:"性别（用于公式）",options:{male:"男性",female:"女性"}},age:{label:"年龄（岁）"},weight:{label:"体重"},height:{label:"身高"}}},"calorie-calculator":{name:"卡路里计算器",short:"计算维持、减重或增重所需的每日卡路里（每日总能量消耗 TDEE）。",intro:"将你的基础代谢率与活动水平相结合，估算每日总能量消耗——即维持当前体重所需的卡路里——并给出逐步减重或增重的起始目标。",howTo:["选择公制或英制，并输入性别、年龄、体重和身高。","选择最符合你一周典型情况的活动水平。","点击「计算」。"],formula:"TDEE = BMR (Mifflin–St Jeor) \xd7 活动系数：久坐 1.2，轻度活动 1.375，中度活动 1.55，高度活动 1.725，运动员 1.9。减重/增重目标按 500 kcal/day 进行调整，约为每周 0.5 kg，减重目标的下限为 1,200 kcal/day。",exampleText:"一位中度活动的 30 岁男性（70 kg、175 cm）维持体重约需 2,556 kcal/day。",faqs:[{q:"我应该严格按照这个数值进食吗？",a:"请将其视为起始估算值。跟踪 2–3 周的体重变化趋势，并根据实际情况按 100–200 kcal 进行调整。"},{q:"500 kcal 的热量缺口对所有人都安全吗？",a:"不一定。摄入量过低、孕期、有进食障碍史以及患有疾病等情况都需要专业指导——本工具仅提供一般性信息。"}],fields:{system:{label:"单位制",options:{metric:"公制（千克、厘米）",imperial:"英制（磅、英寸）"}},sex:{label:"性别（用于公式）",options:{male:"男性",female:"女性"}},age:{label:"年龄（岁）"},weight:{label:"体重"},height:{label:"身高"},activity:{label:"活动水平",options:{sedentary:"久坐（办公为主，几乎不运动）",light:"轻度活动（每周运动 1–3 天）",moderate:"中度活动（每周运动 3–5 天）",active:"高度活动（每周运动 6–7 天）",athlete:"运动员（体力工作 + 训练）"}}}},"discount-calculator":{name:"折扣计算器",short:"根据百分比折扣计算促销价和节省金额，可选计入税费。",intro:"查看任何百分比折扣优惠的最终价格，以及你到底能省多少钱。再填入销售税率，即可得到折扣并计税后的真实到手价。",howTo:["输入原价。","输入折扣百分比。","可选择输入税率，然后点击「计算」。"],formula:"Savings = price \xd7 discount% \xf7 100。Sale price = price − savings。如果填入了税率，税费将按折扣后的价格计算（这是零售业的常见做法）。",exampleText:"一件 $120 的商品优惠 25% 后售价 $90——你节省了 $30。",faqs:[{q:"叠加折扣如何计算？",a:"需要逐个依次计算：一件 $100 的商品先优惠 20% 再优惠 10%，结果是 $72，而不是 $70——第二次折扣是在已经降价后的价格基础上计算的。"},{q:"税费是在折扣前还是折扣后收取？",a:"在大多数零售场景中，厂商优惠券会降低应税价格，而店铺折扣的处理方式可能因司法管辖区而异。本工具按折扣后计税。"}],fields:{price:{label:"原价"},discount:{label:"折扣（%）"},tax:{label:"销售税率 %（可选）"}}},"ecommerce-profit-calculator":{name:"电商单品利润计算器",short:"淘宝、天猫、拼多多、抖音小店卖家的单笔利润：扣掉平台费、快递、推广费与退货损耗，算出单笔净利、净利率、保本售价与保本 ROAS。",intro:"一个卖得好的链接也可能亏钱——平台费、快递、推广费、运费险和退货一扣，账就变了。输入买家实付价、进货成本、快递与包材，选平台（已按常用费率自动填入，按店铺后台的类目费率自行修改），再填单均推广费、每单运费险、退货率与每单退货成本，本工具算出这一单的净利、净利率、推广的保本 ROAS、亏本线售价；填了目标单笔利润，还会反推要卖到多少才达标。",howTo:["选平台——常用费率已自动填入，请按店铺后台显示的类目费率自行修改。","输入买家实付价（扣掉由卖家承担的优惠券、满减后的实际到手价）、进货成本，以及每单的快递与包材费用。","填写单均推广费、每单运费险、退货率与每单退货成本；如需反推定价可填写目标单笔利润，然后点击「计算」。"],formula:"单笔净利 = 买家实付价 − 进货成本 − 快递包材 − 平台费（实付价 \xd7 费率）− 单均推广费 − 运费险 − 退货损耗分摊（退货率 \xd7 每单退货成本）。净利率 = 单笔净利 \xf7 实付价。保本 ROAS = 实付价 \xf7 投放前利润。保本售价 =（进货成本 + 快递包材 + 推广费 + 运费险 + 退货损耗）\xf7（1 − 平台费率）。",exampleText:"淘宝C店（费率 0.6%）一单实付 100 元：进货 40 元、快递包材 5 元、推广 10 元、运费险 1 元、退货率 10%、每单退货成本 8 元——单笔净利 42.6 元，净利率 42.6%，保本 ROAS 1.9，保本售价 57.14 元。",faqs:[{q:"售价填标价还是实付价？",a:"填买家实际付的钱：标价减去由卖家承担的优惠券、店铺满减或平台活动让利。平台费是按实付价收的，填标价会同时高估平台费和利润。"},{q:"平台预设费率到底包含什么？",a:"只是参考值，不是承诺：淘宝C店 0.6% 是支付服务费（类目技术服务费另计），天猫 3.5% 是常用 2–5% 区间的中值，拼多多 0.6% 是常规交易服务费（活动服务费 1–3% 另计），抖音小店 3% 是常用 2–5% 区间的中值。费率按类目与平台当期规则变化，请以店铺后台为准手动修改——费率栏一直可以改。"},{q:"为什么退货损耗要按单均摊，而不是一单退货的成本？",a:"退一单要花返程运费、整烫或报废成本，但不是每单都退。工具把这笔钱摊到所有订单上：退货率 \xd7 每单退货成本。退货率 20%、每单退货成本 15 元，相当于每单先扣 3 元——包括那些没退的订单。"},{q:"保本 ROAS 是什么意思？",a:"推广能跑的最低综合 ROAS：实付价 \xf7 投放前利润。真实综合 ROAS 低于这个数，每单推广订单都在亏钱——哪怕不算推广费时这单看起来是赚的。这个数用的是投放前利润，所以进货、平台费、快递和退货已经扣过了。"},{q:"单笔净利就是店铺的最终利润吗？",a:"不是——它是一单扣完所有单笔变动成本后的贡献。固定成本（房租、人工、软件年费）还要从这里出：单笔净利 \xd7 月有效单量 − 月固定成本，才是店铺的税前净利。"}],fields:{platform:{label:"平台",options:{taobao:"淘宝C店",tmall:"天猫",pdd:"拼多多",douyin:"抖音小店",custom:"自定义平台"}},price:{label:"买家实付价（元）"},cost:{label:"进货成本（元）"},shipping:{label:"快递与包材（元/单）"},feeRate:{label:"平台费率（%）——可选，平台预设"},adCost:{label:"单均推广费（元/单）——可选"},insurance:{label:"运费险（元/单）——可选"},returnRate:{label:"退货率（%）——可选"},returnCost:{label:"每单退货成本（元）——可选"},targetProfit:{label:"目标单笔利润（元）——可选"}}},"loan-calculator":{name:"贷款计算器",short:"计算固定利率贷款的月供、总利息和还款余额。",intro:"根据贷款金额、年利率和期限，估算固定利率贷款的月供。你还可以查看总利息以及每年年末的剩余本金——这些数字能帮助你判断一笔贷款是否负担得起。",howTo:["输入贷款金额。","输入年利率（APR，不含费用）。","输入以年为单位的期限，然后点击「计算」。"],formula:"月供 M = P \xd7 r \xf7 (1 − (1 + r)^−n)，其中 r 为月利率（年利率 \xf7 12），n 为月供期数。当利率为 0% 时，M = P \xf7 n。",exampleText:"一笔 $20,000 的贷款，年利率 6%、期限 5 年，每月月供约为 $386.66，总利息为 $3,199.36。",faqs:[{q:"这包括费用、保险或税费吗？",a:"不包括。它仅计算本金和利息。实际贷款可能还会加上开办费、保险和税费，从而提高真实成本。"},{q:"如果我每月多还款会怎样？",a:"额外还款能更快地降低剩余本金，并可节省大量利息。本估算工具按标准还款计划计算；如需了解额外还款的情况，请向贷款机构索取摊还表。"}],fields:{principal:{label:"贷款金额"},rate:{label:"年利率（%）"},years:{label:"期限（年）"}}},"compound-interest-calculator":{name:"复利计算器",short:"计算储蓄在复利增长和每月定投下的未来价值。",intro:"了解当利息也能产生利息时，储蓄如何增长。输入起始金额、年利率、年数、复利频率，以及可选的每月定投金额，即可得到未来价值，以及其中有多少来自利息。",howTo:["输入起始金额和年利率。","输入年数和复利频率。","可选择添加每月定投金额，然后点击「计算」。"],formula:"本金的未来价值 = P \xd7 (1 + r/f)^(f\xd7t)。定投金额使用等值月利率按月累计。实际年利率为 (1 + r/f)^f − 1。",exampleText:"$10,000 按 5% 年利率、按月复利投资 10 年，将增长至约 $16,470——其中 $6,470 为利息，尚未计入任何定投。",faqs:[{q:"这考虑了通货膨胀或税收吗？",a:"不考虑。它显示的是税前和未考虑通货膨胀的名义增长。实际（经通货膨胀调整后）收益会更低。"},{q:"为什么复利频率重要？",a:"复利越频繁，利息就能越早开始产生利息。这种影响确实存在，但在常见的储蓄利率水平下影响较为有限。"}],fields:{principal:{label:"起始金额"},rate:{label:"年利率（%）"},years:{label:"年数"},frequency:{label:"复利频率",options:{1:"按年",4:"按季",12:"按月",365:"按日"}},contribution:{label:"每月定投（可选）"}}},"unit-converter":{name:"单位换算器",short:"换算长度、重量、温度、时间、数据、速度、面积和体积。",intro:"一个换算器搞定日常生活中容易混淆的单位：米和英里、千克和磅、摄氏度和华氏度、千兆字节和吉比字节等等。选择一个类别，再选择单位，即可得到结果以及所使用的精确换算系数。",howTo:["选择一个类别（长度、重量、温度……）。","选择源单位和目标单位——列表会随类别更新。","输入数值，然后点击「计算」。"],formula:"每个单位都由其相对于该类别基准单位的精确系数定义（例如 1 inch = 0.0254 m，精确值）。Result = value \xd7 factor(from) \xf7 factor(to)。温度使用标准的摄氏度/华氏度/开尔文公式。数据单位使用十进制 KB–TB（1000 的幂）和二进制 KiB–GiB（1024 的幂），并分别标注。",exampleText:"10 千米是 6.2137 英里；100 \xb0F 是 37.78 \xb0C。",faqs:[{q:"为什么 KB 和 KiB 都列出来了？",a:"存储设备厂商使用十进制（1 KB = 1,000 bytes），而操作系统通常报告二进制（1 KiB = 1,024 bytes）。两者都提供，是为了让你能与正在核对的数值相匹配。"},{q:"这些换算系数有多精确？",a:"它们采用国际标准定义（NIST），因此换算结果精确到所显示的位数。"}]},"image-compressor":{name:"图片压缩",short:"在本地压缩 JPG、PNG、WebP 图片——按质量、按比例，或精确压到 100 KB、200 KB、1 MB 等指定大小。",intro:"各种报名、上传表单和平台都对照片大小有硬性限制（比如「小于 200 KB」），图太大就传不上去。本工具完全在你的浏览器里压缩图片，不上传任何服务器：可批量处理 JPG、PNG、WebP，按质量压缩、按比例缩小，或指定一个确切目标大小（100 KB、200 KB、1 MB，也可以自定义 KB 数），由工具自动找出能达标的最高质量。还可以在 JPG、PNG、WebP 之间转换格式，每张图都显示压缩前后的大小对比。",howTo:["选择或拖入一张或多张 JPG、PNG、WebP 图片。","选择压缩方式：按质量、按比例缩小，或压到指定大小（预设 100 KB / 200 KB / 1 MB，也可自定义 KB）。","如需转换格式可选择输出格式，然后点击「全部压缩」，逐张下载或全部下载。"],formula:"压缩使用浏览器内置的图像编码器重新编码。在「压到指定大小」模式下，工具会二分查找编码质量；若最低质量仍超标，则逐级缩小像素尺寸，直到输出小于或等于目标大小——与专业工具相同的试错方法，全程本地运行。手机照片的 EXIF 方向会被正确处理，竖拍照片不会变横；注意重新编码会去除照片中的位置等 EXIF 元数据。",exampleText:"一张 3 MB 的手机照片压到 200 KB 目标时，会在不缩小分辨率的前提下，使用能达标的最高质量完成压缩。",faqs:[{q:"图片会被上传到服务器吗？",a:"不会。全部压缩都在你的浏览器里通过 Canvas 完成。你可以先打开本页再断网验证——断网后工具照常工作。"},{q:"为什么压到指定大小时分辨率有时会变小？",a:"目标很小（比如 100 KB）时，只降质量在原分辨率下可能压不到。这时工具会逐级缩小尺寸直到达标，并标明新的尺寸。"},{q:"PNG 和 JPG 哪个压得更小？",a:"照片类图片用 JPG 或 WebP 通常小得多；PNG 是无损格式，适合截图、Logo 和带文字或透明背景的图片。照片从 PNG 转成 JPG，一般能减小 80%–95%。"},{q:"压缩后画质会变差吗？",a:"JPG/WebP 是有损压缩，用少量细节换大幅体积。质量 80 以上时肉眼很难看出差别；下载前可以对比原图与压缩后的大小再决定。"}]},"heic-to-jpg-converter":{name:"HEIC 转 JPG",short:"把 iPhone 的 HEIC、HEIF 照片在浏览器里转成 JPG——批量转换、打包下载 ZIP，不上传任何照片。",intro:"iPhone 照片默认存为 HEIC，很多网站、报名表单和老应用只认 JPG。本工具把 HEIC、HEIF 照片完全在你的浏览器里转成标准 JPG，不上传任何服务器：把 iPhone 里的一批照片拖进来，选好 JPG 质量，一次全部转换，然后逐张下载 JPG，或一次性打包成一个 ZIP 下载。原图从不离开你的设备。",howTo:["选择或拖入一张或多张 HEIC、HEIF 照片。","设置 JPG 质量（92 是大小与画质的平衡点）。","点击「全部转换」，然后逐张下载 JPG，或一次性打包下载 ZIP。"],formula:"HEIC 照片先由浏览器里的 WebAssembly 版 libheif（开源 HEIF 解码器）解码，再用浏览器内置编码器重编码为 JPG。解码时会按照片的方向信息处理，竖拍照片不会变横；重编码会去除原 HEIC 文件中的位置等元数据，JPG 只保留按你选定质量输出的图像本身。",exampleText:"10 张共 24 MB 的 iPhone 照片，用质量 92 转换只需几秒，即可上传到任何要求 JPG 的地方。",faqs:[{q:"照片会被上传到服务器吗？",a:"不会。解码与转换完全在你的浏览器里通过 WebAssembly 完成。你可以先打开本页再断网验证——页面加载后断网，工具照常工作。"},{q:"为什么 iPhone 照片是 HEIC？",a:"HEIC（高效图像容器）能在同样画质下只占 JPG 约一半的体积，所以苹果把它设为 iPhone 默认格式。代价是兼容性：很多网站、Windows 应用和老设备打不开它，分享前转成 JPG 是最稳妥的做法。"},{q:"转换会损失画质吗？",a:"JPG 是有损格式，转换后的照片与 HEIC 原图不是逐字节相同。质量 92 时肉眼很难看出差别；想要更小的文件可以调低质量，想要保留最多细节可以调到接近 100。"},{q:"一个 HEIC 文件里有多张照片（连拍/实况）怎么办？",a:"有些 HEIC 文件内含不止一张图。工具会把文件里的每一张都转出来，命名为 photo-1.jpg、photo-2.jpg，以此类推，不会悄悄丢掉任何一张。"}]},"china-income-tax-calculator":{name:"个税计算器（个税＋五险一金到手工资）",short:"按累计预扣法计算到手工资：五险一金、专项附加扣除、城市参数预设，支持由到手工资反推税前工资。",intro:"一份中国工资真正到手多少，取决于三件事：个人缴纳的五险一金、每月 5000 元减除费用与专项附加扣除，以及让月度个税随月份推进而升高的累计预扣法。本工具三者都算：可选北京、上海、广州、深圳、杭州、成都的参数预设，也可以完全自定义缴费基数与比例，输出逐月预扣明细、全年个税与全年到手。还支持反推：输入你想到手的工资，算出需要谈到的税前工资。",howTo:["选择城市预设，或切换到自定义参数。","输入月税前工资；或切换到反推模式，输入目标到手工资。","填写每月专项附加扣除与公积金比例，点击「计算」。"],formula:"每月个人缴费 = 缴费基数（工资按当地上下限夹取）\xd7 个人比例（养老 8%、医疗 2%、失业 0.5%，广东为 0.2%；公积金按单位选定的 5%–12%）。第 m 个月累计应纳税所得额 = m \xd7（工资 − 5000 − 个人缴费 − 专项附加扣除）；累计税额按综合所得年度税率表计算（36000 以内 3%，其后 10%/20%/25%/30%/35%/45% 并扣速算扣除数）；当月预扣 = 累计税额较上月的新增部分。",exampleText:"月薪 30000 元、每月五险一金个人缴费 4500 元、专项附加扣除 2000 元时，1 月预扣个税 555 元、2 月 625 元——与累计预扣规则公布时给出的测算示例一致。",faqs:[{q:"为什么每个月扣的个税越来越多？",a:"累计预扣法对年初至今的累计收入计税。年初累计收入还在 3% 档内，跨过 36000 元、144000 元等节点后，后面月份适用更高税率，所以同样的工资越到年底扣得越多。看全年总额才准确。"},{q:"城市参数是官方的吗？",a:"每个预设都标注了来源通告与核对日期（北京、上海采用 2026 年 7 月起执行的基数，广东采用全省统一养老基数）。基数与比例每年都会调整，公积金比例由单位选定，结果请按估算看待，并可按自己的工资条修改参数。"},{q:"能算年终奖或换过工作的情况吗？",a:"不能。本工具按同一单位、全年每月工资不变建模。单独计税的年终奖、年中入职或换工作、汇算清缴的退补税不在范围内。"},{q:"工资数据会被保存吗？",a:"不会。计算完全在你的浏览器本地完成，不上传、不保存。"}]}};function s(a,e){var o;if("en"===e)return a;let l=r[a.slug];if(!l)return a;let t=null===(o=a.fields)||void 0===o?void 0:o.map(a=>{var e,o,t,r;let s=null===(e=l.fields)||void 0===e?void 0:e[a.key];return s?{...a,label:null!==(t=s.label)&&void 0!==t?t:a.label,placeholder:null!==(r=s.placeholder)&&void 0!==r?r:a.placeholder,options:null===(o=a.options)||void 0===o?void 0:o.map(a=>{var e,o;let[l,t]=a;return[l,null!==(o=null===(e=s.options)||void 0===e?void 0:e[l])&&void 0!==o?o:t]})}:a});return{...a,name:l.name,short:l.short,intro:l.intro,howTo:l.howTo,formula:l.formula,exampleText:l.exampleText,faqs:l.faqs,fields:t}}function i(a,e){return"zh"===e&&t.Ix[a]?t.Ix[a]:l.R6[a]}}}]);